<?php
// Final Comprehensive System Fix
echo "🔧 PVGS ERP Final System Fix\n";
echo "============================\n\n";

$dbPath = __DIR__ . '/database/database.sqlite';

try {
    $pdo = new PDO('sqlite:' . $dbPath);
    $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
    
    echo "✓ Database connected\n";
    
    // 1. Get students that were created
    echo "\n📚 Getting student records...\n";
    $students = $pdo->query("SELECT id, user_id, name FROM students")->fetchAll(PDO::FETCH_ASSOC);
    echo "Found " . count($students) . " student records\n";
    
    // 2. Create fee structures if missing
    echo "\n💰 Setting up fee structures...\n";
    
    $feeStructureCheck = $pdo->query("SELECT COUNT(*) FROM fee_structures")->fetchColumn();
    if ($feeStructureCheck == 0) {
        $feeStructureStmt = $pdo->prepare("INSERT INTO fee_structures (program_id, academic_year, name, tuition_fee, development_fee, exam_fee, library_fee, lab_fee, other_fees, total_fee, total_installments, installment_type, is_active, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, datetime('now'), datetime('now'))");
        
        // BSc Computer Science fee structure
        $feeStructureStmt->execute([1, '2024-25', 'BSc Computer Science Annual Fee', 45000, 8000, 3000, 2000, 5000, 2000, 65000, 2, 'semester']);
        
        // BCom fee structure  
        $feeStructureStmt->execute([2, '2024-25', 'BCom Annual Fee', 35000, 6000, 2500, 1500, 2000, 1500, 48500, 2, 'semester']);\n        \n        echo "  + Created fee structures\n";\n    } else {\n        echo "  ✓ Fee structures already exist\n";\n    }\n    \n    // 3. Add student fees\n    echo "\n💳 Adding student fee records...\n";\n    \n    $studentFeeStmt = $pdo->prepare("INSERT OR IGNORE INTO student_fees (student_id, fee_structure_id, academic_year, gross_amount, scholarship_amount, discount_amount, fine_amount, net_amount, paid_amount, balance_amount, status, current_installment, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))");\n    \n    foreach ($students as $student) {\n        $feeStructureId = ($student['id'] % 2) + 1; // Alternate between fee structures\n        $grossAmount = $feeStructureId == 1 ? 65000 : 48500;\n        $scholarshipAmount = rand(0, 5000);\n        $discountAmount = rand(0, 2000);\n        $fineAmount = 0;\n        $netAmount = $grossAmount - $scholarshipAmount - $discountAmount + $fineAmount;\n        $paidAmount = rand(20000, $netAmount - 5000);\n        $balanceAmount = $netAmount - $paidAmount;\n        $status = $balanceAmount > 0 ? 'partial' : 'paid';\n        $currentInstallment = $paidAmount > ($netAmount / 2) ? 2 : 1;\n        \n        $studentFeeStmt->execute([$student['id'], $feeStructureId, '2024-25', $grossAmount, $scholarshipAmount, $discountAmount, $fineAmount, $netAmount, $paidAmount, $balanceAmount, $status, $currentInstallment]);\n        echo "  + Added fee record for: {$student['name']}\n";\n    }\n    \n    // 4. Add attendance records\n    echo "\n📊 Adding attendance records...\n";\n    \n    $subjects = $pdo->query("SELECT id FROM subjects")->fetchAll(PDO::FETCH_COLUMN);\n    $attendanceStmt = $pdo->prepare("INSERT OR IGNORE INTO attendance_records (student_id, subject_id, attendance_date, status, marked_by, created_at, updated_at) VALUES (?, ?, ?, ?, 1, datetime('now'), datetime('now'))");\n    \n    foreach ($students as $student) {\n        foreach ($subjects as $subjectId) {\n            // Generate 30 days of attendance\n            for ($day = 1; $day <= 30; $day++) {\n                $date = date('Y-m-d', strtotime("-$day days"));\n                // 85% attendance rate\n                $status = (rand(1, 100) <= 85) ? 'present' : 'absent';\n                \n                $attendanceStmt->execute([$student['id'], $subjectId, $date, $status]);\n            }\n        }\n    }\n    echo "  + Added attendance records for all students\n";\n    \n    // 5. Add exam results\n    echo "\n📝 Adding exam results...\n";\n    \n    $resultStmt = $pdo->prepare("INSERT OR IGNORE INTO exam_results (student_id, subject_id, exam_type, marks_obtained, max_marks, percentage, grade, result, academic_year, semester, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))");\n    \n    foreach ($students as $student) {\n        foreach ($subjects as $subjectId) {\n            $maxMarks = 100;\n            $marksObtained = rand(60, 95);\n            $percentage = ($marksObtained / $maxMarks) * 100;\n            \n            $grade = 'F';\n            if ($percentage >= 90) $grade = 'A+';\n            elseif ($percentage >= 80) $grade = 'A';\n            elseif ($percentage >= 70) $grade = 'B+';\n            elseif ($percentage >= 60) $grade = 'B';\n            elseif ($percentage >= 50) $grade = 'C';\n            \n            $result = $percentage >= 40 ? 'pass' : 'fail';\n            \n            $resultStmt->execute([$student['id'], $subjectId, 'semester', $marksObtained, $maxMarks, $percentage, $grade, $result, '2024-25', 1]);\n        }\n    }\n    echo "  + Added exam results for all students\n";\n    \n    // 6. Add principal user if missing\n    echo "\n👑 Checking principal account...\n";\n    \n    $principalCheck = $pdo->query("SELECT COUNT(*) as count FROM users WHERE user_type = 'principal' OR email LIKE '%principal%'")->fetch();\n    \n    if ($principalCheck['count'] == 0) {\n        $principalStmt = $pdo->prepare("INSERT INTO users (name, email, password, user_type, is_active, created_at, updated_at) VALUES (?, ?, ?, 'principal', 1, datetime('now'), datetime('now'))");\n        $hashedPassword = password_hash('password123', PASSWORD_DEFAULT);\n        $principalStmt->execute(['Dr. Priya Mehta', 'principal@pvgs.edu', $hashedPassword]);\n        echo "  + Added principal account: principal@pvgs.edu\n";\n    } else {\n        echo "  ✓ Principal account already exists\n";\n    }\n    \n    // 7. Update existing users to ensure they have passwords\n    echo "\n🔐 Updating user passwords...\n";\n    \n    $users = $pdo->query("SELECT id, email, password FROM users WHERE password IS NULL OR password = ''")->fetchAll(PDO::FETCH_ASSOC);\n    \n    if (!empty($users)) {\n        $passwordStmt = $pdo->prepare("UPDATE users SET password = ? WHERE id = ?");\n        $defaultPassword = password_hash('password123', PASSWORD_DEFAULT);\n        \n        foreach ($users as $user) {\n            $passwordStmt->execute([$defaultPassword, $user['id']]);\n            echo "  + Updated password for: {$user['email']}\n";\n        }\n    } else {\n        echo "  ✓ All users have passwords\n";\n    }\n    \n    // 8. Final verification\n    echo "\n✅ Final System Status:\n";\n    \n    $counts = [\n        'users' => $pdo->query("SELECT COUNT(*) FROM users")->fetchColumn(),\n        'students' => $pdo->query("SELECT COUNT(*) FROM students")->fetchColumn(),\n        'student_fees' => $pdo->query("SELECT COUNT(*) FROM student_fees")->fetchColumn(),\n        'attendance_records' => $pdo->query("SELECT COUNT(*) FROM attendance_records")->fetchColumn(),\n        'exam_results' => $pdo->query("SELECT COUNT(*) FROM exam_results")->fetchColumn(),\n        'fee_structures' => $pdo->query("SELECT COUNT(*) FROM fee_structures")->fetchColumn()\n    ];\n    \n    foreach ($counts as $table => $count) {\n        echo "  - $table: $count records\n";\n    }\n    \n    // Show user types\n    echo "\n👥 User Distribution:\n";\n    $userTypes = $pdo->query("SELECT user_type, COUNT(*) as count FROM users GROUP BY user_type")->fetchAll(PDO::FETCH_ASSOC);\n    foreach ($userTypes as $type) {\n        echo "  - {$type['user_type']}: {$type['count']} users\n";\n    }\n    \n    echo "\n🎉 System is now fully functional!\n";\n    echo "\n📋 Login Credentials (all use password: password123):\n";\n    echo "- Principal: principal@pvgs.edu\n";\n    echo "- Admin: admin@pvgs.edu\n";\n    echo "- Faculty: rajesh.kumar@pvgs.edu\n";\n    echo "- Student: aarav.sharma@pvgs.edu\n";\n    echo "- Student: vivaan.patel@pvgs.edu\n";\n    \n    echo "\n🚀 You can now test the system at http://localhost:8000\n";\n    \n} catch (Exception $e) {\n    echo "❌ Error: " . $e->getMessage() . "\n";\n    echo "Line: " . $e->getLine() . "\n";\n}